// Generates src/mdct_tables.h: every constant of the textbook MDCT (sine window, DCT-IV pre/post twiddles, FFT twiddles) as exact
// hexadecimal double literals, so every decoder uses bit-identical constants instead of its own sin/cos (cross-platform determinism).
#include <cstdio>
#include <cmath>
int main() {
    const int N = 512, M = N / 2; const double PI = 3.14159265358979323846264338327950288;
    FILE* f = fopen("mdct_tables.h", "w");
    fprintf(f, "// SPDX-FileCopyrightText: 2026 mtq0605\n// SPDX-License-Identifier: Apache-2.0\n// generated by tools/gen_mdct_tables.cpp: exact double constants of the textbook MDCT, N = %d (do not edit)\n#pragma once\nnamespace mdct {\n", N);
    fprintf(f, "static const double WIN[%d] = {", 2 * N); for (int n = 0; n < 2 * N; n++) fprintf(f, "%s%a", n ? "," : "", sin(PI * (n + 0.5) / (2 * N))); fprintf(f, "};\n");
    // DCT-IV of size N via an N/2-point complex FFT: pre-twiddle exp(-i*2pi*(n+1/8)/(2N)), post-twiddle exp(-i*2pi*(k+1/8)/(2N)).
    // The constant phase is split evenly between the two twiddles.
    fprintf(f, "static const double PRE_C[%d] = {", M); for (int n = 0; n < M; n++) fprintf(f, "%s%a", n ? "," : "", cos(-2 * PI * (n + 0.125) / (2 * N))); fprintf(f, "};\n");
    fprintf(f, "static const double PRE_S[%d] = {", M); for (int n = 0; n < M; n++) fprintf(f, "%s%a", n ? "," : "", sin(-2 * PI * (n + 0.125) / (2 * N))); fprintf(f, "};\n");
    fprintf(f, "static const double POST_C[%d] = {", M); for (int k = 0; k < M; k++) fprintf(f, "%s%a", k ? "," : "", cos(-2 * PI * (k + 0.125) / (2 * N))); fprintf(f, "};\n");
    fprintf(f, "static const double POST_S[%d] = {", M); for (int k = 0; k < M; k++) fprintf(f, "%s%a", k ? "," : "", sin(-2 * PI * (k + 0.125) / (2 * N))); fprintf(f, "};\n");
    fprintf(f, "static const double FFT_C[%d] = {", M / 2); for (int k = 0; k < M / 2; k++) fprintf(f, "%s%a", k ? "," : "", cos(-2 * PI * k / M)); fprintf(f, "};\n");
    fprintf(f, "static const double FFT_S[%d] = {", M / 2); for (int k = 0; k < M / 2; k++) fprintf(f, "%s%a", k ? "," : "", sin(-2 * PI * k / M)); fprintf(f, "};\n");
    // bit-reversal permutation of the M-point FFT input: index i with its log2(M) bits in reverse order
    int bits = 0; while ((1 << bits) < M) bits++;
    fprintf(f, "static const unsigned short BITREV[%d] = {", M);
    for (int i = 0; i < M; i++) { int r = 0; for (int b = 0; b < bits; b++) if (i & (1 << b)) r |= 1 << (bits - 1 - b); fprintf(f, "%s%d", i ? "," : "", r); }
    fprintf(f, "};\n");
    fprintf(f, "static const double SCALE = %a;   // 1/sqrt(N/2): orthonormal DCT-IV\n}\n", 1.0 / sqrt((double)M));
    fclose(f); return 0; }
